**Orb Rush**: collect glowing orbs and dodge the red spiked hazards. More hazards appear and they move faster over time. Reach 1000 points to win.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Orb Rush</title>
<style>
  html,body{margin:0;height:100%;background:#05060f;display:flex;align-items:center;justify-content:center;font-family:system-ui,Segoe UI,Arial,sans-serif;color:#cfe;}
  #wrap{position:relative;}
  canvas{display:block;background:radial-gradient(ellipse at center,#111a33 0%,#05060f 80%);border:2px solid #234;border-radius:8px;box-shadow:0 0 30px #0af4;cursor:crosshair;}
  #help{text-align:center;font-size:13px;color:#8ab;margin-top:8px;}
</style>
</head>
<body>
<div id="wrap">
  <canvas id="c" width="800" height="560"></canvas>
  <div id="help">Move: Arrow keys / WASD, or hold the mouse button to steer toward the cursor &middot; P: pause &middot; M: mute</div>
</div>
<script>
(function(){
  const cv = document.getElementById('c');
  const ctx = cv.getContext('2d');
  const W = cv.width, H = cv.height;
  const WIN_SCORE = 1000;

  window.gameState = { score: 0, state: "menu" };

  // ---------- Audio (generated) ----------
  let actx = null, muted = false;
  function initAudio(){
    if (!actx) {
      try { actx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e) { actx = null; }
    }
    if (actx && actx.state === 'suspended') actx.resume();
  }
  function tone(freq, dur, type, vol, slideTo){
    if (!actx || muted) return;
    const t = actx.currentTime;
    const o = actx.createOscillator(), g = actx.createGain();
    o.type = type || 'sine';
    o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
    g.gain.setValueAtTime(vol || 0.15, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(actx.destination);
    o.start(t); o.stop(t + dur + 0.02);
  }
  const sfx = {
    orb(combo){ tone(520 + Math.min(combo,10)*40, 0.12, 'sine', 0.15, 1200 + combo*60); },
    hit(){ tone(220, 0.35, 'sawtooth', 0.2, 50); },
    over(){ tone(400,0.25,'triangle',0.2,200); setTimeout(()=>tone(260,0.5,'triangle',0.2,80),220); },
    win(){ [523,659,784,1046].forEach((f,i)=>setTimeout(()=>tone(f,0.25,'square',0.1),i*130)); },
    start(){ tone(330,0.1,'square',0.1,660); },
    level(){ tone(880,0.15,'triangle',0.1,1320); }
  };

  // ---------- Input ----------
  const keys = {};
  const mouse = { x: W/2, y: H/2, down: false };
  window.addEventListener('keydown', e => {
    const k = e.key.toLowerCase();
    if (['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)) e.preventDefault();
    keys[k] = true;
    initAudio();
    if (k === 'm') { muted = !muted; return; }
    if (state === 'playing' && k === 'p') { paused = !paused; return; }
    if ((k === 'enter' || k === ' ') && state !== 'playing') startGame();
  });
  window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });
  function mpos(e){
    const r = cv.getBoundingClientRect();
    mouse.x = (e.clientX - r.left) * (W / r.width);
    mouse.y = (e.clientY - r.top) * (H / r.height);
  }
  cv.addEventListener('mousemove', mpos);
  cv.addEventListener('mousedown', e => {
    mpos(e); initAudio();
    if (state !== 'playing') { startGame(); return; }
    mouse.down = true;
  });
  window.addEventListener('mouseup', () => { mouse.down = false; });
  cv.addEventListener('contextmenu', e => e.preventDefault());

  // ---------- Game state ----------
  let state = 'menu', paused = false;
  let player, orbs, hazards, particles, score, lives, elapsed, level, spawnTimer, combo, comboTimer, invuln, shake, best = 0, overTimer = 0;

  function setState(s){ state = s; window.gameState.state = s; }
  function setScore(v){ score = v; window.gameState.score = v; }

  function reset(){
    player = { x: W/2, y: H/2, r: 12, speed: 280 };
    orbs = []; hazards = []; particles = [];
    setScore(0);
    lives = 3; elapsed = 0; level = 1; spawnTimer = 0;
    combo = 0; comboTimer = 0; invuln = 1.5; shake = 0; paused = false;
    for (let i = 0; i < 4; i++) spawnOrb();
    for (let i = 0; i < 2; i++) spawnHazard();
  }
  function startGame(){
    if (state === 'playing') return;
    if (state === 'over' || state === 'won') { if (overTimer > 0) return; }
    reset();
    setState('playing');
    sfx.start();
  }

  function rand(a,b){ return a + Math.random()*(b-a); }
  function dist(a,b){ return Math.hypot(a.x-b.x, a.y-b.y); }

  function spawnOrb(){
    let o, tries = 0;
    do {
      o = { x: rand(30, W-30), y: rand(50, H-30), r: 8, t: Math.random()*6, hue: rand(160, 300), big: Math.random() < 0.12 };
      if (o.big) o.r = 12;
      tries++;
    } while (player && dist(o, player) < 80 && tries < 20);
    orbs.push(o);
  }
  function spawnHazard(){
    // spawn from an edge, away from the player
    let x, y, tries = 0;
    do {
      const side = Math.floor(Math.random()*4);
      if (side === 0) { x = rand(0,W); y = -20; }
      else if (side === 1) { x = W+20; y = rand(0,H); }
      else if (side === 2) { x = rand(0,W); y = H+20; }
      else { x = -20; y = rand(0,H); }
      tries++;
    } while (player && Math.hypot(x-player.x, y-player.y) < 200 && tries < 20);
    const speed = rand(90, 130) + level * 14;
    const tx = rand(W*0.2, W*0.8), ty = rand(H*0.2, H*0.8);
    const a = Math.atan2(ty - y, tx - x);
    const homing = level >= 3 && Math.random() < Math.min(0.1 + level*0.04, 0.4);
    hazards.push({ x, y, vx: Math.cos(a)*speed, vy: Math.sin(a)*speed, r: rand(11, 17), rot: 0, spin: rand(-4,4), homing, speed, entering: true });
  }
  function burst(x, y, hue, n, spd){
    for (let i = 0; i < n; i++) {
      const a = Math.random()*Math.PI*2, s = rand(spd*0.3, spd);
      particles.push({ x, y, vx: Math.cos(a)*s, vy: Math.sin(a)*s, life: rand(0.4, 0.9), max: 0.9, hue });
    }
  }

  // ---------- Update ----------
  function update(dt){
    if (overTimer > 0) overTimer -= dt;
    // particles always animate
    for (let i = particles.length-1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx*dt; p.y += p.vy*dt; p.vx *= 0.96; p.vy *= 0.96; p.life -= dt;
      if (p.life <= 0) particles.splice(i,1);
    }
    if (shake > 0) shake = Math.max(0, shake - dt*30);
    if (state !== 'playing' || paused) return;

    elapsed += dt;
    const newLevel = 1 + Math.floor(elapsed / 15);
    if (newLevel > level) { level = newLevel; sfx.level(); burst(W/2, 30, 50, 20, 200); }

    // player movement
    let dx = 0, dy = 0;
    if (keys['arrowleft'] || keys['a'] || keys['q']) dx -= 1;
    if (keys['arrowright'] || keys['d']) dx += 1;
    if (keys['arrowup'] || keys['w'] || keys['z']) dy -= 1;
    if (keys['arrowdown'] || keys['s']) dy += 1;
    if (dx || dy) {
      const l = Math.hypot(dx, dy);
      player.x += dx/l * player.speed * dt;
      player.y += dy/l * player.speed * dt;
    } else if (mouse.down) {
      const mx = mouse.x - player.x, my = mouse.y - player.y, l = Math.hypot(mx, my);
      if (l > 3) {
        const step = Math.min(l, player.speed * dt);
        player.x += mx/l*step; player.y += my/l*step;
      }
    }
    player.x = Math.max(player.r, Math.min(W - player.r, player.x));
    player.y = Math.max(player.r, Math.min(H - player.r, player.y));
    if (invuln > 0) invuln -= dt;

    // combo decay
    if (comboTimer > 0) { comboTimer -= dt; if (comboTimer <= 0) combo = 0; }

    // orbs
    for (let i = orbs.length-1; i >= 0; i--) {
      const o = orbs[i];
      o.t += dt*3;
      if (dist(o, player) < o.r + player.r) {
        combo++; comboTimer = 2;
        const pts = (o.big ? 50 : 10) * Math.min(1 + Math.floor(combo/5), 4);
        setScore(score + pts);
        burst(o.x, o.y, o.hue, o.big ? 24 : 12, 180);
        sfx.orb(combo);
        orbs.splice(i,1);
        spawnOrb();
        if (score >= WIN_SCORE) {
          best = Math.max(best, score);
          setState('won'); overTimer = 0.8; sfx.win();
          burst(player.x, player.y, 60, 60, 300);
          return;
        }
      }
    }

    // hazard spawning: target count grows with time
    const target = 2 + Math.floor(elapsed / 6);
    spawnTimer -= dt;
    if (hazards.length < Math.min(target, 28) && spawnTimer <= 0) {
      spawnHazard();
      spawnTimer = Math.max(0.4, 2 - level*0.15);
    }

    // hazards
    for (const h of hazards) {
      if (h.homing) {
        const a = Math.atan2(player.y - h.y, player.x - h.x);
        h.vx += Math.cos(a) * 60 * dt; h.vy += Math.sin(a) * 60 * dt;
        const s = Math.hypot(h.vx, h.vy), max = h.speed * 0.9;
        if (s > max) { h.vx *= max/s; h.vy *= max/s; }
      }
      h.x += h.vx*dt; h.y += h.vy*dt; h.rot += h.spin*dt;
      if (h.entering) {
        if (h.x > h.r && h.x < W-h.r && h.y > h.r && h.y < H-h.r) h.entering = false;
      } else {
        if (h.x < h.r) { h.x = h.r; h.vx = Math.abs(h.vx); }
        if (h.x > W-h.r) { h.x = W-h.r; h.vx = -Math.abs(h.vx); }
        if (h.y < h.r) { h.y = h.r; h.vy = Math.abs(h.vy); }
        if (h.y > H-h.r) { h.y = H-h.r; h.vy = -Math.abs(h.vy); }
      }
      if (invuln <= 0 && dist(h, player) < h.r*0.8 + player.r) {
        lives--; invuln = 1.6; shake = 12; combo = 0;
        burst(player.x, player.y, 0, 30, 260);
        sfx.hit();
        if (lives <= 0) {
          best = Math.max(best, score);
          setState('over'); overTimer = 0.8;
          setTimeout(sfx.over, 150);
          return;
        }
      }
    }
  }

  // ---------- Draw ----------
  function glowCircle(x, y, r, color, blur){
    ctx.save();
    ctx.shadowColor = color; ctx.shadowBlur = blur;
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
    ctx.restore();
  }
  function drawGrid(t){
    ctx.save();
    ctx.strokeStyle = 'rgba(60,120,200,0.07)'; ctx.lineWidth = 1;
    const off = (t*10) % 40;
    for (let x = -40 + off; x < W; x += 40) { ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
    for (let y = -40 + off; y < H; y += 40) { ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
    ctx.restore();
  }
  function drawHazard(h){
    ctx.save();
    ctx.translate(h.x, h.y); ctx.rotate(h.rot);
    ctx.shadowColor = h.homing ? '#f0f' : '#f33'; ctx.shadowBlur = 15;
    ctx.fillStyle = h.homing ? '#c2f' : '#e22';
    ctx.beginPath();
    const spikes = 8;
    for (let i = 0; i < spikes*2; i++) {
      const rr = i % 2 === 0 ? h.r : h.r*0.55;
      const a = i * Math.PI / spikes;
      ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
    }
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#300';
    ctx.beginPath(); ctx.arc(0,0,h.r*0.25,0,Math.PI*2); ctx.fill();
    ctx.restore();
  }
  function centerText(txt, y, size, color, glow){
    ctx.save();
    ctx.font = `bold ${size}px system-ui,Segoe UI,Arial,sans-serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    if (glow) { ctx.shadowColor = glow; ctx.shadowBlur = 20; }
    ctx.fillText(txt, W/2, y);
    ctx.restore();
  }

  let menuOrbs = [];
  for (let i = 0; i < 14; i++) menuOrbs.push({ x: rand(0,W), y: rand(0,H), vx: rand(-30,30), vy: rand(-30,30), hue: rand(160,300), t: Math.random()*6 });

  function draw(t){
    ctx.clearRect(0,0,W,H);
    ctx.save();
    if (shake > 0) ctx.translate(rand(-shake,shake), rand(-shake,shake));
    drawGrid(t);

    if (state === 'menu') {
      for (const o of menuOrbs) {
        o.x = (o.x + o.vx/60 + W) % W; o.y = (o.y + o.vy/60 + H) % H; o.t += 0.05;
        glowCircle(o.x, o.y, 7 + Math.sin(o.t)*2, `hsl(${o.hue},100%,65%)`, 20);
      }
    } else {
      for (const o of orbs) {
        const r = o.r + Math.sin(o.t)*2;
        glowCircle(o.x, o.y, r, `hsl(${o.hue},100%,${o.big ? 75 : 62}%)`, o.big ? 35 : 22);
        glowCircle(o.x, o.y, r*0.4, '#fff', 5);
      }
      for (const h of hazards) drawHazard(h);
      if (state === 'playing' && !(invuln > 0 && Math.floor(invuln*10) % 2 === 0)) {
        glowCircle(player.x, player.y, player.r, '#4ff', 25);
        glowCircle(player.x, player.y, player.r*0.55, '#eff', 6);
      }
    }
    for (const p of particles) {
      ctx.globalAlpha = Math.max(0, p.life / p.max);
      ctx.fillStyle = p.hue === 0 ? '#f55' : `hsl(${p.hue},100%,65%)`;
      ctx.fillRect(p.x-2, p.y-2, 4, 4);
    }
    ctx.globalAlpha = 1;
    ctx.restore();

    // HUD
    if (state === 'playing' || state === 'over' || state === 'won') {
      ctx.save();
      ctx.font = 'bold 20px system-ui,Arial,sans-serif';
      ctx.fillStyle = '#dff'; ctx.textBaseline = 'top';
      ctx.fillText('Score: ' + score + ' / ' + WIN_SCORE, 14, 12);
      ctx.textAlign = 'center';
      ctx.fillText('Level ' + level, W/2, 12);
      ctx.textAlign = 'right';
      ctx.fillText('Lives:', W - 14 - 3*22, 12);
      for (let i = 0; i < 3; i++) {
        ctx.globalAlpha = i < lives ? 1 : 0.2;
        glowCircle(W - 14 - (2-i)*22 - 8, 23, 7, '#4ff', 10);
      }
      ctx.globalAlpha = 1;
      if (combo >= 5 && state === 'playing') {
        ctx.textAlign = 'left'; ctx.fillStyle = '#ff6';
        ctx.fillText('Combo x' + Math.min(1 + Math.floor(combo/5), 4), 14, 38);
      }
      ctx.restore();
    }

    if (state === 'menu') {
      ctx.fillStyle = 'rgba(0,0,10,0.45)'; ctx.fillRect(0,0,W,H);
      centerText('ORB RUSH', 150, 72, '#6ff', '#0ff');
      centerText('Collect glowing orbs. Avoid the red spikes.', 230, 20, '#cde');
      centerText('Big orbs = 50 pts. Chain pickups quickly for a combo multiplier.', 262, 16, '#9bc');
      centerText('Hazards multiply and speed up. Purple ones hunt you!', 290, 16, '#9bc');
      centerText('Move: Arrow keys / WASD   or   hold mouse button to steer', 340, 17, '#dfe');
      centerText('3 lives  \u00b7  Reach ' + WIN_SCORE + ' points to win  \u00b7  P pause  \u00b7  M mute', 370, 15, '#9bc');
      if (Math.floor(t*2) % 2 === 0) centerText('Press ENTER / SPACE or CLICK to start', 440, 24, '#ff6', '#fa0');
      if (best) centerText('Best: ' + best, 490, 16, '#9bc');
    } else if (state === 'over' || state === 'won') {
      ctx.fillStyle = 'rgba(0,0,10,0.6)'; ctx.fillRect(0,0,W,H);
      if (state === 'over') centerText('GAME OVER', 200, 64, '#f55', '#f00');
      else centerText('YOU WIN!', 200, 64, '#6f6', '#0f0');
      centerText('Score: ' + score, 270, 28, '#fff');
      centerText('Best: ' + best + '   \u00b7   Level reached: ' + level, 310, 18, '#9bc');
      if (overTimer <= 0 && Math.floor(t*2) % 2 === 0) centerText('Press ENTER / SPACE or CLICK to play again', 390, 22, '#ff6', '#fa0');
    } else if (paused) {
      ctx.fillStyle = 'rgba(0,0,10,0.5)'; ctx.fillRect(0,0,W,H);
      centerText('PAUSED', H/2 - 10, 50, '#6ff', '#0ff');
      centerText('Press P to resume', H/2 + 40, 18, '#cde');
    }
    if (muted) { ctx.fillStyle = '#789'; ctx.font = '12px sans-serif'; ctx.textAlign = 'right'; ctx.fillText('muted', W-10, H-10); ctx.textAlign = 'left'; }
  }

  // ---------- Loop ----------
  let last = performance.now();
  function loop(now){
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    update(dt);
    draw(now / 1000);
    requestAnimationFrame(loop);
  }
  reset(); setState('menu'); setScore(0);
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
